  'my.title': 'సెట్టింగ్‌లు మరియు సేవ్ చేసిన డేటా', 'my.intro': 'Nivesh Sahayak ప్రతి డాక్యుమెంట్ టూల్‌ను ఒకే చోట సెట్ చేయండి: మీ బిజినెస్‌లు, కస్టమర్లు మరియు సప్లయర్లు, ఐటమ్స్ మరియు సర్వీసులు, నంబరింగ్ మరియు డిఫాల్ట్‌లు. అంతా ఈ బ్రౌజర్‌లోనే ఉంటుంది. మాకు ఏమీ పంపబడదు.',
