  'my.search': 'వెతకండి', 'my.ph': 'పేరు, నంబర్ లేదా కోడ్ టైప్ చేయండి', 'my.edit': 'మార్చండి', 'my.savech': 'మార్పులు సేవ్ చేయండి', 'my.cancel': 'క్యాన్సిల్', 'my.noname': '(పేరు లేదు)',
  'my.empty': 'ఇక్కడ ఇంకా ఏమీ సేవ్ కాలేదు. టూల్స్ వాడుతున్న కొద్దీ ఇది నిండుతుంది.', 'my.vault': 'ఈ బ్రౌజర్‌లో Nivesh Sahayak టూల్స్ అన్నీ ఇదే డేటాను వాడతాయి.', 'my.local': 'ఈ బ్రౌజర్‌లోనే ఉంచబడింది.',
  'my.wipe.t': 'అన్నీ డిలీట్ చేయండి', 'my.wipe.p': 'ఈ బ్రౌజర్ నుండి సేవ్ చేసిన బిజినెస్‌లు, కస్టమర్లు, ఐటమ్స్, డాక్యుమెంట్లు అన్నీ తీసేస్తుంది. తర్వాత అవసరం పడొచ్చు అనుకుంటే ముందుగా బ్యాకప్ ఫైల్ సేవ్ చేసుకోండి.',
  'my.wipe.b': 'ఈ డివైస్‌లో అన్నీ డిలీట్ చేయండి', 'my.wipe.c1': 'ఈ డివైస్‌లో సేవ్ చేసిన బిజినెస్‌లు, కస్టమర్లు, ఐటమ్స్, డాక్యుమెంట్లు అన్నీ డిలీట్ చేయాలా? అవసరం పడొచ్చు అనుకుంటే ముందుగా బ్యాకప్ ఫైల్ సేవ్ చేసుకోండి.',
  'my.wipe.c2': 'నిర్ధారించడానికి DELETE అని టైప్ చేయండి.', 'my.wiped': 'ఈ డివైస్ నుండి అన్నీ డిలీట్ అయ్యాయి.', 'my.c.del': '"{name}" డిలీట్ చేయాలా? బ్యాకప్ ఫైల్ లేకపోతే ఇది తిరిగి రాదు.', 'my.saved': 'సేవ్ అయింది.',
