  'hub.toolsp': 'ఇక్కడ మీరు జోడించేదంతా ఈ బ్రౌజర్‌లో Nivesh Sahayak ప్రతి డాక్యుమెంట్ టూల్‌లో సూచనగా కనిపిస్తుంది. ఏదీ తనంతట తానే నిండదు: మీరే ఎంచుకుంటారు.',
