  'hub.p.item': 'వస్తువులు మరియు సర్వీసులు, వాటి HSN/SAC కోడ్, యూనిట్, రేట్ మరియు GST తో. ఏ టూల్‌లోనైనా ఎంచుకుంటే లైన్ నిండుతుంది.',
  'hub.p.doc': 'ఈ బ్రౌజర్‌లో సేవ్ చేసిన ప్రతి డాక్యుమెంట్. తెరవడం, కాపీ చేయడం లేదా పెయిడ్ అని మార్క్ చేయడం దాన్ని తయారు చేసిన టూల్‌లోనే చేయండి.',
