  "ev.lt5": "2017-18 నుండి ఏ సంవత్సరంలోనైనా మీ టర్నోవర్ ₹5 కోట్లు దాటకపోతే ఇ-ఇన్వాయిస్ మీకు తప్పనిసరి కాదు.",
  "ev.old180": "180 రోజుల కంటే పాత డాక్యుమెంట్‌కు పోర్టల్ ఇ-వే బిల్ చేయదు.",
  "ev.smallst": "{st} లోపల ఇ-వే బిల్ సాధారణంగా ₹{v} కంటే ఎక్కువైతేనే కావాలి (వేరే రాష్ట్రానికి ₹50,000 కంటే ఎక్కువ; వేరే రాష్ట్రానికి వెళ్లే జాబ్ వర్క్, హస్తకళలకు ఏ విలువకైనా కావాలి).",
  "ev.fromirn": "మీ బిజినెస్ ఇ-ఇన్వాయిస్ చేయాల్సి ఉంటే, ఈ ఇన్వాయిస్ ఇ-వే బిల్‌ను పోర్టల్ దాని IRN నుండి మాత్రమే చేస్తుంది: “ఇ-ఇన్‌వాయిస్‌తో పాటు ఇ-వే బిల్ కూడా చేయండి” టిక్ చేసి ఇ-ఇన్వాయిస్ ఫైల్ చేయండి.",
  "ev.tidchk": "ట్రాన్స్‌పోర్టర్ ID చివరి అక్షరం సరిపోలడం లేదు. టైపింగ్ తప్పేమో ఒకసారి చూసుకోండి.",
  "ei.rmnote": "మీరు ఈ IRN ను పోర్టల్‌లో క్యాన్సిల్ చేసి ఉంటే, ఈ ఇన్వాయిస్ నంబర్ మళ్లీ ఎప్పటికీ రిజిస్టర్ కాదు. సరైన ఇన్వాయిస్‌ను కొత్త నంబర్‌తో చేయండి.",
  /* tax rule fixes, bills (4 Nov 2026) */
  "hub.reg": "GST రిజిస్ట్రేషన్",
  "hub.rg.regular": "రెగ్యులర్ GST రిజిస్ట్రేషన్",
  "hub.rg.comp": "కంపోజిషన్ స్కీమ్",
  "hub.rg.unreg": "GSTలో రిజిస్టర్ కాలేదు",
  "hub.rg.sez": "SEZ యూనిట్",
  "v.b2c": "GSTIN లేని కస్టమర్‌కు ₹50,000 లేదా ఎక్కువ బిల్‌పై GST నియమాల ప్రకారం కస్టమర్ పేరు, చిరునామా, రాష్ట్రం కావాలి.",
  "c.r28": "1 ఫిబ్రవరి 2026 నుండి 28% GST తీసేశారు (ఆ వస్తువులు ఇప్పుడు 40% లేదా 18%). అయినా 28%తో సేవ్ చేయాలా?",
  "c.cash2l": "ఇన్‌కమ్ టాక్స్ చట్టం ప్రకారం ఒక బిల్‌కు ₹2 లక్షలు లేదా ఎక్కువ నగదు తీసుకోవడం నిషేధం (అంతే మొత్తం జరిమానా). అయినా సేవ్ చేయాలా?",
  /* Phase 1 additions */
  "v.orig": "ఈ నోట్ ఏ ఇన్‌వాయిస్ కోసమో దాని నంబర్, తేదీ టైప్ చేయండి. GST నియమాల ప్రకారం నోట్‌పై అవి ఉండాలి.",
  "v.naddr": "GSTIN లేని కొనుగోలుదారుకు, వారి చిరునామా, రాష్ట్రం టైప్ చేయండి.",
  "c.cn30": "ఈ క్రెడిట్ నోట్ తేదీ, ఆ ఇన్‌వాయిస్ ఆర్థిక సంవత్సరం ముగిసిన తర్వాత వచ్చే 30 నవంబర్ తర్వాత ఉంది (లేదా ఆ సంవత్సరపు వార్షిక రిటర్న్ అంతకంటే ముందే ఫైల్ చేసి ఉంటే, దాని తర్వాత). ఆ తేదీ తర్వాత దానిపై GST తగ్గించలేరు (బిజినెస్ డాక్యుమెంట్‌గా నోట్ చెల్లుతుంది). అయినా సేవ్ చేయాలా?",
  "s.tds": "చెల్లించినవారు కట్ చేసిన TDS (₹)",
  "s.h.tds": "చెల్లించినవారు TDS కట్ చేస్తేనే. రసీదుపై TDS, సెటిల్ అయిన పూర్తి బిల్ మొత్తం కనిపిస్తాయి.",
  "c.cash10k": "ఇన్‌కమ్ టాక్స్ చట్టం ప్రకారం ఒకే వ్యక్తికి ఒక రోజులో ₹10,000 కంటే ఎక్కువ నగదు చెల్లింపు బిజినెస్ ఖర్చుగా అనుమతించబడదు (ట్రాన్స్‌పోర్టర్లకు ₹35,000). అయినా సేవ్ చేయాలా?",
  "doc.self": "సెల్ఫ్ ఇన్‌వాయిస్",
