  "f.self": "సెల్ఫ్ ఇన్‌వాయిస్ మేకర్ (రివర్స్ చార్జ్)",
  "hub.self": "రివర్స్ చార్జ్‌లో రిజిస్టర్ కాని సప్లయర్ల నుండి కొన్నవాటికి సెల్ఫ్ ఇన్‌వాయిస్",
