  "v.sigst": "సెల్ఫ్ ఇన్‌వాయిస్‌కు మీ GSTIN కావాలి: రిజిస్టర్ అయిన కొనుగోలుదారు మాత్రమే దీన్ని ఇస్తారు.",
  "v.recv": "సరుకులు లేదా సర్వీసులు అందిన తేదీ టైప్ చేయండి.",
  "c.si30": "ఈ సెల్ఫ్ ఇన్‌వాయిస్ తేదీ, సరుకులు లేదా సర్వీసులు అందిన 30 రోజుల తర్వాత ఉంది. నియమాల ప్రకారం 30 రోజుల్లోపు ఇవ్వాలి. అయినా సేవ్ చేయాలా?",
  "k.ref": "అడ్వాన్స్ వాపసు",
  "kh.ref": "ఏమీ సప్లై కాకపోవడంతో వాపసు ఇచ్చిన అడ్వాన్స్ డబ్బు. GST నియమాలు దీన్ని రీఫండ్ వోచర్ అంటాయి.",
  "s.gstadv": "ఈ అడ్వాన్స్‌లో GST కలిసి ఉంది (సర్వీసులు)",
  "s.h.gstadv": "సర్వీసుల కోసం వచ్చిన అడ్వాన్స్‌కు టిక్ చేయండి: అప్పుడు రసీదు, దానిలోని GST చూపే రసీదు వోచర్‌గా మారుతుంది. సరుకుల అడ్వాన్స్‌పై GST ఉండదు; సాధారణ అడ్వాన్స్ రసీదే రసీదు వోచర్‌గా పనిచేస్తుంది.",
  "s.samestate": "నా రాష్ట్రమే",
  "s.sacf": "SAC కోడ్",
  "s.rv": "రసీదు వోచర్ నంబర్",
  "s.h.rv": "అడ్వాన్స్ వచ్చినప్పుడు మీరు ఇచ్చిన రసీదు వోచర్.",
  "s.rvdate": "రసీదు వోచర్ తేదీ",
  "s.v.rv": "ఈ రీఫండ్ ఏ రసీదు వోచర్ కోసమో దాని నంబర్ టైప్ చేయండి.",
  "s.lg.tdsrcm": "TDS, రివర్స్ చార్జ్",
  "s.tdssec": "TDS సెక్షన్",
  "s.h.tdssec": "సెక్షన్ ఎంచుకోండి లేదా టైప్ చేయండి, ఉదాహరణకు 393 (పాత 194C). సందేహం ఉంటే మీ అకౌంటెంట్‌ను అడగండి.",
