  "s.rcm": "ఈ చెల్లింపుపై GST మేమే కట్టాలి (రివర్స్ చార్జ్)",
  "s.h.rcm": "ఉదాహరణకు రిజిస్టర్ కాని సప్లయర్‌కు లేదా రివర్స్ చార్జ్‌లో ఉన్న గూడ్స్ ట్రాన్స్‌పోర్ట్ ఏజెన్సీకి చెల్లింపు.",
  "s.rcmrate": "రివర్స్ చార్జ్ GST రేట్ %",
  "c.nopan": "మీరు TDS కట్ చేస్తున్నారు కానీ డబ్బు అందుకునేవారి PAN ఖాళీగా ఉంది. PAN లేకుండా TDS సాధారణంగా 20% (సరుకుల కొనుగోలుపై 5%). అయినా సేవ్ చేయాలా?",
