  "s.r.old": "పాత రెజీమ్",
  "s.ptstate": "ప్రొఫెషనల్ టాక్స్ కోసం రాష్ట్రం",
  "s.pt.none": "రాష్ట్రం ఎంచుకోండి",
  "s.pt.manual": "ఈ రాష్ట్రపు ప్రొఫెషనల్ టాక్స్ ఇంకా మా టేబుల్‌లో లేదు. ప్రొఫెషనల్ టాక్స్ లైన్‌లో టైప్ చేయండి.",
  "s.pfbtn2": "PF, ESI, ప్రొఫెషనల్ టాక్స్, TDS లెక్కించండి",
  "s.h.pf2": "PF: బేసిక్‌పై 12% (₹25,000 వరకు బేసిక్‌పై); ESI: గ్రాస్ ₹21,000 లేదా తక్కువ ఉంటే 0.75%; ప్రొఫెషనల్ టాక్స్: పైన ఎంచుకున్న రాష్ట్రం నుండి; TDS: ఈ నెల గ్రాస్ × 12, FY 2026-27 స్లాబ్‌లు, స్టాండర్డ్ డిడక్షన్‌తో. మీ నియమాలతో సరిచూసుకోండి.",
  "s.w.wages": "బేసిక్ పే గ్రాస్‌లో సగం కంటే తక్కువ. లేబర్ కోడ్‌ల ప్రకారం అదనపు అలవెన్సులు PF, గ్రాట్యుటీకి వేతనంగా లెక్కకు వస్తాయి.",
