  "bk.h.s2": "ఒక ఐటమ్‌కు ఒక వరుస. ఒకే ఇన్‌వాయిస్ నంబర్ ఉన్న వరుసలు కలిసి ఒక ఇన్‌వాయిస్ అవుతాయి. మీ సొంత షీట్ హెడ్డింగ్‌లు మావి లాగే ఉంటే అది కూడా పని చేస్తుంది.",
  "bk.h.s2e": "ఒక ఐటమ్‌కు ఒక వరుస. ఒకే డాక్యుమెంట్ నంబర్ ఉన్న వరుసలు కలిసి ఒక ఇ-వే బిల్ అవుతాయి. వాహనం ఖాళీగా వదిలితే Part A మాత్రమే తయారవుతుంది; వాహనం తర్వాత జోడించవచ్చు.",
  "bk.reading": "ఫైల్ చదువుతోంది…",
