  "bk.badfile": "ఈ ఫైల్ చదవలేకపోయాం. .xlsx లేదా .csv ఫైల్ ఎంచుకోండి.",
  "bk.nohead": "కాలమ్ హెడ్డింగ్‌లు దొరకలేదు (కనీసం డాక్యుమెంట్ నంబర్, ఐటమ్ ఉండాలి). మా టెంప్లేట్‌తో మొదలుపెట్టండి.",
