  "bk.s3": "పోర్టల్ జవాబును లోడ్ చేయండి",
  "bk.h.s3": "అప్‌లోడ్ తర్వాత, పోర్టల్ నుంచి రిజల్ట్ (JSON లేదా Excel) డౌన్‌లోడ్ చేసి ఇక్కడ ఎంచుకోండి. IRN, Ack నంబర్, సంతకం చేసిన QR కోడ్ ప్రతి సేవ్ చేసిన ఇన్‌వాయిస్‌కు చేరతాయి, ప్రింట్‌కు రెడీగా.",
  "bk.h.s3e": "జనరేట్ చేసిన తర్వాత, పోర్టల్ నుంచి రిజల్ట్ డౌన్‌లోడ్ చేసి ఇక్కడ ఎంచుకోండి. ఇ-వే బిల్ నంబర్లు సేవ్ చేసిన ఇన్‌వాయిస్‌లకూ, కింద ఉన్న వాహనం ఫైల్‌కూ చేరతాయి.",
  "bk.got": "జవాబులో దొరికినవి: {n}. సేవ్ చేసిన ఇన్‌వాయిస్‌లతో సరిపోలినవి: {k}.",
  "bk.open": "తెరిచి ప్రింట్ చేయండి",
  "bk.notsaved": "ఇక్కడ సేవ్ కాలేదు",
