  "bk.pb": "వాహనాన్ని తర్వాత జోడించండి (Part B)",
  "bk.h.pb": "వాహనం లేకుండా తయారు చేసిన ఇ-వే బిల్లుల కోసం, లేదా సరుకు వేరే వాహనంలోకి మారినప్పుడు. పోర్టల్ వాహనం అప్‌డేట్ ఫైల్‌ను తయారు చేస్తుంది. Part A మాత్రమే ఉన్న ఇ-వే బిల్‌కు, వ్యాలిడిటీ ఈ అప్‌డేట్ నుంచి మొదలవుతుంది.",
