  "g3.w.rcmv": "వోచర్ {no}: రివర్స్ ఛార్జ్ పన్ను CGST + SGSTగా తీసుకోబడింది. సరఫరాదారు వేరే రాష్ట్రంలో ఉంటే (IGST) బాక్స్‌లను మార్చండి.",
  "g3.w.nogstin": "{p} నుంచి వచ్చిన పర్చేజ్ బిల్లు {no} కు సరైన సరఫరాదారు GSTIN లేదు, అందువల్ల దాని ITC GSTR-2Bలో కనిపించదు.",
  "g3.w.2b": "బాక్స్ 4(A)(5)లోని ITC మీరు సేవ్ చేసిన పర్చేజ్ బిల్లులు మరియు ఖర్చుల నుంచి వస్తుంది. GSTR-2Bలో కనిపించేది మాత్రమే క్లెయిమ్ చేయండి; అది తక్కువగా ఉంటే GSTR-2B మొత్తాన్ని టైప్ చేయండి.",
  "g3.w.neg": "లభించే క్రెడిట్ సున్నా కంటే తక్కువగా ఉంది: తిరగరాసినవి క్రెడిట్ కంటే ఎక్కువ. తేడాను నగదుగా చెల్లించాలి; మీ అకౌంటెంట్‌ను అడగండి.",

