  "g2.s.only2b": "GSTR-2Bలో ఉన్నాయి, మీ పర్చేజ్ బిల్లుల్లో లేవు",
  "g2.s.onlybooks": "మీ పర్చేజ్ బిల్లుల్లో ఉన్నాయి, GSTR-2Bలో లేవు",
  "g2.s.noitc": "GSTR-2Bలో ITC లభించదని ఉంది",
  "g2.s.nofile": "ఈ GSTR-2Bలో ఏమీ లేని సరఫరాదారులు",
  "g2.h.ok": "అదే సరఫరాదారు, నంబర్, మొత్తం, తేదీ. ఈ క్రెడిట్‌ను క్లెయిమ్ చేయవచ్చు.",
  "g2.h.diff": "రెండింటిలోనూ ఉన్నాయి, కానీ మొత్తాలు తేడాగా ఉన్నాయి. సరఫరాదారుతో బిల్లును సరిచూసుకోండి; GSTR-2Bలో కనిపించేది మాత్రమే క్లెయిమ్ చేయండి.",
  "g2.h.numdiff": "అదే సరఫరాదారు మరియు మొత్తం, కానీ బిల్లు నంబర్ వేరే విధంగా రాశారు. సాధారణంగా టైపింగ్ తేడా: మీ ఎంట్రీని సరిచేయండి.",
  "g2.h.only2b": "సరఫరాదారు ఈ బిల్లులను రిపోర్ట్ చేశారు, కానీ అవి మీ పుస్తకాల్లో సేవ్ కాలేదు. వస్తువులు లేదా సేవలు మీకు అందితే వాటిని ఎంటర్ చేయండి, లేకపోతే సరఫరాదారును సరిచేయమని అడగండి.",
  "g2.h.onlybooks": "ఈ తేదీల మీ బిల్లులను సరఫరాదారు ఇంకా రిపోర్ట్ చేయలేదు. అవి GSTR-2Bలో కనిపించే వరకు ITC క్లెయిమ్ చేయకండి; సరఫరాదారుకు గుర్తు చేయండి.",
  "g2.h.noitc": "పోర్టల్‌లో ITC లభించదని చూపే బిల్లులు (ఉదాహరణకు సరఫరా స్థలం సరఫరాదారు రాష్ట్రంలో ఉండటం, లేదా కాల పరిమితి).",
  "g2.h.nofile": "ఈ కాలంలో మీ బిల్లుల్లో ఏదీ ఈ సరఫరాదారులు రిపోర్ట్ చేయలేదు. వారు GSTR-1 ఫైల్ చేయకపోయి ఉండవచ్చు.",
