  "td.no.q": "ఇంకా TDS లేదు: ఈ విక్రేత నుంచి ఈ ఏడాది కొనుగోళ్లు {l} దాటలేదు.",
  "td.catch": "ఈ చెల్లింపు ఏడాది మొత్తాన్ని పరిమితి దాటిస్తుంది, అందువల్ల TDS మొత్తం పైనా లెక్కించబడుతుంది, TDS లేకుండా ముందే చెల్లించిన {y} తో సహా. అందులో కొంతదానిపై ఇప్పటికే TDS కోత చేసి ఉంటే, తేడా మాత్రమే కోత చేయండి.",
  "td.nopan": "సరైన PAN లేకపోతే రేటు 20% లేదా సాధారణ రేటుకు రెట్టింపు (వస్తువుల కొనుగోలుకు 5%) అందులో ఎక్కువది. గ్రహీతను వారి PAN అడగండి.",
  "td.trans": "10 లేదా అంతకంటే తక్కువ గూడ్స్ క్యారేజీలు కలిగి PANతో డిక్లరేషన్ ఇచ్చే ట్రాన్స్‌పోర్టర్‌కు TDS లేకుండా చెల్లించవచ్చు.",
  "td.q": "గత ఏడాది మీ టర్నోవర్ ₹10 కోట్ల కంటే ఎక్కువ ఉంటేనే కోత చేయండి, ఈ విక్రేత నుంచి ఏడాది కొనుగోళ్లలో ₹50 లక్షల పైబడిన భాగంపై మాత్రమే.",
  "td.ib": "పన్ను ఆడిట్ లేని వ్యక్తి చెల్లించే అద్దెకు, ఏడాది లేదా అద్దె కాలంలోని చివరి నెల అద్దె నుంచి TDS ఒక్కసారి మాత్రమే కోత చేస్తారు.",
  "td.oldnote": "2026 ఏప్రిల్ 1 కంటే ముందు చెల్లింపులకు ఆదాయపు పన్ను చట్టం, 1961 వర్తిస్తుంది: పాత సెక్షన్ నంబర్ వాడండి.",
  "td.h.reg": "మీరు కోత చేసిన TDS (మీ పేమెంట్ వోచర్ల నుంచి)",
  "td.h.regh": "voucher.niveshsahayak.in లో లేదా యాప్‌లో TDS రేటుతో సేవ్ చేసిన వోచర్లు, నెల మరియు సెక్షన్ వారీగా, జమ చేయాల్సిన తేదీతో.",
  "td.h.cut": "కస్టమర్లు మీ నుంచి కోత చేసిన TDS (మీ రసీదుల నుంచి)",
  "td.h.cuth": "“TDS deducted by payer” ఉన్న రసీదులు. క్లెయిమ్ చేసే ముందు ప్రతిదీ మీ వార్షిక పన్ను స్టేట్‌మెంట్‌లో కనిపిస్తోందో చూసుకోండి.",
