  "pl.lineh": "టైప్ చేసిన లైన్ అంటే ట్రయల్ బ్యాలెన్స్‌లోని ఒక ఖాతా, దాని హెడ్‌తో. చాలా సర్దుబాట్లకు ఒకదాన్ని ఒకటి సరిచేసే రెండు లైన్లు కావాలి, ఉదా. తరుగుదల (డెబిట్), అంతే మొత్తం ఫర్నిచర్ నుంచి తగ్గింపు (క్రెడిట్).",
