  "b1.tcson": "ఈ బిల్లుపై TCS వసూలు చేయండి",
  "b1.tcsh": "అమ్మేవారు ఆదాయపు పన్ను వసూలు చేయాల్సిన అమ్మకాలకే: ఆదాయపు పన్ను చట్టం 2025 సెక్షన్ 394 (ఇంతకు ముందు సెక్షన్ 206C). ఫైనాన్స్ చట్టం 2026 తర్వాతి రేట్లు: మద్యం, తునికాకు, కలప లేదా అటవీ ఉత్పత్తి, స్క్రాప్, బొగ్గు, లిగ్నైట్ లేదా ఇనుప ఖనిజం 2%; ₹10 లక్షలకు పైబడిన వాహనం లేదా నోటిఫై చేసిన వస్తువు 1%; విదేశీ టూర్ ప్యాకేజీ 2%; పార్కింగ్, టోల్ ప్లాజా, గని 2%. 1 నుండి 5 వస్తువులపై కొనేవారు అవి తయారీకి, వ్యాపారానికి కాదు అని రాసి ఇస్తే TCS లేదు. ఇతర సరుకులపై TCS లేదు (₹50 లక్షల పాత నియమం లేదు).",
