  "b1.v_tcs": "TCS రేట్ రాయండి, లేదా TCS టిక్ తీసేయండి.",
  "b1.v_tcs10": "వాహనం లేదా నోటిఫైడ్ వస్తువులపై TCS ఒక ఐటమ్ విలువ ₹10 లక్షలు దాటితేనే (నోటిఫికేషన్ 36/2025 పై CBDT FAQ, 23 ఏప్రిల్ 2025). ఈ బిల్లులో అలాంటి ఐటమ్ ఏదీ లేదు. TCS టిక్ తీసేయండి.",
  "b1.c_tcs10g": "GST లేకుండా ఏ ఐటమ్ ₹10 లక్షలు దాటలేదు, GST కలిపితేనే దాటింది. యాక్ట్‌లో \"వ్యాల్యూ\" అని ఉంది; ఈ లిమిట్‌లో GST లెక్కించాలా వద్దా అని ఏ సర్క్యులర్ తేల్చలేదు. ఈ బిల్లుపై TCS తీసుకోవాలా?",
  "b1.tcsbh": "CBDT సర్క్యులర్ 17/2020 (పేరా 4.6.1, పాత సెక్షన్ 206C కోసం): TCS అందిన మొత్తంపై GST తో సహా తీసుకుంటారు; GST, డిస్కౌంట్ లేదా రిటర్న్ కోసం ఏమీ తగ్గించరు. టాక్సబుల్ వ్యాల్యూను మీ CA చెబితేనే ఎంచుకోండి.",
  "b1.cntcs": "బిల్లు {no} పై {v} TCS ఉంది. ఈ క్రెడిట్ నోట్ ఆ TCS ను తగ్గించదు: CBDT సర్క్యులర్ 17/2020 (పేరా 4.6.1) ప్రకారం సేల్స్ రిటర్న్‌కు ఎలాంటి అడ్జస్ట్‌మెంట్ లేదు. కొనుగోలుదారు ఈ TCS ను తమ ఇన్‌కమ్ టాక్స్ రిటర్న్‌లో క్లెయిమ్ చేస్తారు.",
