  "b1.tcsnopan": "కొనేవారి సరైన PAN లేదు: TCS {r}% (రేట్‌కు రెట్టింపు లేదా 5%, ఏది ఎక్కువైతే అది, 20% వరకు, సెక్షన్ 397(2)).",
