  "b1.rep_see": "చూసి వేయండి",
  "b1.bin": "రీసైకిల్ బిన్",
  "b1.binp": "తొలగించిన బిజినెస్, పార్టీ, ఐటెమ్, డాక్యుమెంట్లు ఇక్కడ {n} రోజులు ఉంటాయి, తర్వాత శాశ్వతంగా పోతాయి. రీస్టోర్ చేస్తే మునుపటిలాగే తిరిగి వస్తుంది.",
  "b1.binnone": "రీసైకిల్ బిన్ ఖాళీగా ఉంది.",
  "b1.binempty": "బిన్‌ను ఇప్పుడే ఖాళీ చేయండి",
  "b1.binemptyc": "రీసైకిల్ బిన్‌లోని అన్నీ శాశ్వతంగా తీసేయాలా?",
