  "b1.daysleft": "{n} రోజులు మిగిలాయి",
  "b1.cdel": "{x} తొలగించాలా? ఇది 30 రోజులు రీసైకిల్ బిన్‌లో ఉంటుంది, అక్కడి నుండి రీస్టోర్ చేయవచ్చు.",
  "b1.binned": "రీసైకిల్ బిన్‌కు వెళ్లింది. 30 రోజుల వరకు రీస్టోర్ చేయవచ్చు.",
  "b1.hist": "మార్పుల రికార్డు",
  "b1.changes": "మార్పులు",
  "b1.changesof": "మార్పులు: {no}",
  "b1.nolog": "ఇంకా ఏ మార్పూ నమోదు కాలేదు.",
  "b1.thisdev": "ఈ డివైస్",
  "b1.logp": "ఏ Nivesh Sahayak సైట్‌లోనైనా బిజినెస్, పార్టీ, ఐటెమ్ లేదా డాక్యుమెంట్ జోడించినా, మార్చినా, తొలగించినా లేదా రీస్టోర్ చేసినా తేదీ, సమయం, పేరు, ఏమి మారింది అనేది ఇక్కడ నమోదవుతుంది. ఈ ఎంట్రీలను మార్చలేరు, తీసేయలేరు.",
  "b1.logrule": "1 ఏప్రిల్ 2023 నుండి కంపెనీలు ఇలాంటి ఆడిట్ ట్రెయిల్ ఉంచే అకౌంట్స్ సాఫ్ట్‌వేర్ వాడాలి (కంపెనీల (అకౌంట్స్) నిబంధనలు 2014, నియమం 3(1)). ఇది ఈ బ్రౌజర్‌లో, మీ బ్యాకప్ ఫైల్‌లో ఉంటుంది.",
  "b1.logmore": "{n} లో కొత్త 300 చూపిస్తున్నాం. అన్నింటికీ Excel ఫైల్ డౌన్‌లోడ్ చేయండి.",
  "b1.itemn": "ఐటెమ్ {n}",
