  "b1.h_who": "ఈ డివైస్‌లో చేసే ప్రతి మార్పుతో మార్పుల రికార్డులో కనిపిస్తుంది.",
  "b1.lock": "ఈ తేదీకి ముందు డాక్యుమెంట్లు లాక్ చేయండి",
  "b1.h_lock": "ఈ రోజుకు ముందు తేదీ ఉన్న డాక్యుమెంట్లను ఏ సైట్‌లోనూ జోడించలేరు, మార్చలేరు, తొలగించలేరు (పేమెంట్ వచ్చిందని గుర్తు పెట్టడం పని చేస్తుంది). GST రిటర్న్ ఫైల్ చేసిన తర్వాత లేదా లెక్కలు ముగించిన తర్వాత వాడండి.",
  "b1.lockc": "{d} కి ముందు తేదీ ఉన్న అన్ని డాక్యుమెంట్లను లాక్ చేయాలా? ఈ తేదీ తీసేసే వరకు మార్చలేరు.",
  "b1.unlockc": "పాత డాక్యుమెంట్లు మళ్లీ మార్చేలా అన్‌లాక్ చేయాలా?",
  "b1.locked": "లాక్ ఉంది: {d} కి ముందు తేదీ ఉన్న డాక్యుమెంట్లను మార్చలేరు. ముందుగా సెట్టింగ్స్, సేవ్ డేటా › సెట్టింగ్స్‌లో లాక్ తేదీ తీసేయండి.",
  "b1.pin_t": "PIN లాక్",
  "b1.pin_on": "ఆన్",
  "b1.pin_off": "ఆఫ్",
  "b1.pin_p": "PIN పెడితే మీ డేటా ఈ స్క్రీన్‌పై, Nivesh Sahayak యాప్‌లో PIN వేసే వరకు దాగి ఉంటుంది. ఇది స్క్రీన్ లాక్, ఎన్‌క్రిప్షన్ కాదు: డేటా మారదు, డాక్యుమెంట్ సైట్లు బిల్ నింపడానికి దాన్ని చదవగలవు. PIN మర్చిపోతే తిరిగి రావడానికి ఒకటే దారి: ఈ బ్రౌజర్ డేటాను తుడిచి బ్యాకప్ ఫైల్ రీస్టోర్ చేయండి.",
  "b1.pin_cur": "ప్రస్తుత PIN",
  "b1.pin_new": "కొత్త PIN (4 నుండి 8 అంకెలు)",
