  "b1.unlock": "తెరవండి",
  "b1.pin_wait": "చాలాసార్లు ప్రయత్నించారు. {n} సెకన్లు ఆగండి.",
  "b1.forgot": "PIN మర్చిపోయారా?",
  "b1.forgotp": "PIN ను చూపించలేం, రీసెట్ చేయలేం. లోపలికి రావడానికి ఈ బ్రౌజర్ డేటాను తుడిచి మీ చివరి బ్యాకప్ ఫైల్‌ను రీస్టోర్ చేయండి. ఆ బ్యాకప్ తర్వాత సేవ్ అయినవన్నీ పోతాయి.",
  "b1.erase": "ఈ బ్రౌజర్ డేటాను తుడిచేయండి",
  "b1.erase_c1": "ఈ బ్రౌజర్‌లో సేవ్ అయిన ప్రతి బిజినెస్, పార్టీ, ఐటెమ్, డాక్యుమెంట్ తుడిచేయాలా? మీ బ్యాకప్ ఫైల్ మాత్రమే వాటిని తిరిగి తేగలదు.",
  "b1.erased": "తుడిచేశాం. ఇప్పుడు మీ బ్యాకప్ ఫైల్ ఎంచుకోండి.",
  "b1.wiz": "ఒక్క నిమిషంలో మొదలుపెట్టండి",
  "b1.wizp": "మీ బిజినెస్ వివరాలు ప్రతి బిల్లుపై ప్రింట్ అవుతాయి. తర్వాత మార్చవచ్చు, మరిన్ని బిజినెస్‌లు జోడించవచ్చు.",
  "b1.wiz_gst": "GST రిజిస్ట్రేషన్ లేకపోతే ఖాళీగా వదలండి.",
  "b1.wiz_go": "సేవ్ చేసి మొదలుపెట్టండి",
  "b1.wiz_done": "మీ బిజినెస్ సేవ్ అయింది. ఇప్పుడు కస్టమర్లు, ఐటెమ్‌లు జోడించండి, లేదా మొదటి బిల్లు వేయండి.",
  "b1.samp_try": "ముందు శాంపిల్ డేటాతో చూడండి",
  "b1.samp_h": "శాంపిల్ డేటా అంటే \"Sharma Hardware (sample)\" అనే కల్పిత బిజినెస్, కస్టమర్లు, ఐటెమ్‌లు, బిల్లులు, ఒక పేమెంట్, ఒక కొనుగోలుతో, అన్నింటిపై శాంపిల్ అని గుర్తు. ఒక్క ట్యాప్‌తో అంతా పోతుంది.",
  "b1.samp_on": "శాంపిల్ డేటా ఆన్: శాంపిల్ అని ఉన్న రికార్డులు కల్పితం.",
  "b1.samp_rm": "అన్ని శాంపిల్ రికార్డులు తీసేయండి",
  "b1.samp_rmc": "ప్రతి శాంపిల్ రికార్డూ తీసేయాలా? మీ సొంత రికార్డులు ఉంటాయి.",
  "b1.samp_gone": "{n} శాంపిల్ రికార్డులు తీసేశాం.",
  "b1.samp_added": "శాంపిల్ డేటా జోడించాం. చూసి, ఒక్క ట్యాప్‌తో తీసేయండి.",
  "b1.sample": "శాంపిల్",
  "b1.xl": "Excel డౌన్‌లోడ్",
  "b1.xl_reg": "రిజిస్టర్లు Excel లో",
