  "b1.xl_fail": "Excel ఫైల్ తయారవలేదు. ఇంటర్నెట్ చూసి మళ్లీ ప్రయత్నించండి.",
  "b1.xl_none": "ఈ కాలంలో ఏమీ లేదు.",
  "b1.rp_t": "రిపోర్టులు Excel లో",
  "b1.rp_p": "ప్రతి బటన్ ఎంచుకున్న తేదీల Excel ఫైల్‌ను డౌన్‌లోడ్ చేస్తుంది. కాలమ్ పేర్లు ఇంగ్లీషులో ఉంటాయి, ఏ అకౌంటెంట్ అయినా చదవగలరు.",
  "b1.rp_sales": "సేల్స్ రిజిస్టర్",
  "b1.rp_salesp": "ప్రతి బిల్లు, క్రెడిట్ నోట్, డెబిట్ నోట్, టాక్సబుల్ వాల్యూ, CGST, SGST, IGST, TCS, మొత్తంతో.",
  "b1.rp_purchases": "కొనుగోలు రిజిస్టర్",
  "b1.rp_purchasesp": "కొనుగోలు బిల్లులు, రిటర్న్‌లు, సెల్ఫ్ ఇన్‌వాయిస్‌లు, ఖర్చులు GST తో.",
  "b1.rp_dues": "బాకీలు",
  "b1.rp_duesp": "ఈరోజు ఎవరి నుండి రావాలి, ఎవరికి ఇవ్వాలి, ఎంత పాతవి, క్రెడిట్ లిమిట్, డ్యూ డేట్ దాటిన మొత్తంతో.",
  "b1.rp_stock": "స్టాక్ సమ్మరీ",
  "b1.rp_stockp": "ప్రతి ఐటెమ్ ఓపెనింగ్, వచ్చినది, వెళ్లినది, మిగిలినది, సగటు ధరపై విలువతో.",
  "b1.rp_statements": "పార్టీ స్టేట్‌మెంట్లు",
  "b1.rp_statementsp": "ప్రతి పార్టీకి ఒక షీట్ (40 వరకు): ఓపెనింగ్ బ్యాలెన్స్, ప్రతి ఎంట్రీ, క్లోజింగ్ బ్యాలెన్స్.",
  "b1.rp_items": "ఐటెమ్‌లు, రేట్లు",
  "b1.rp_itemsp": "ప్రతి ఐటెమ్ కేటగిరీ, MRP, రిటైల్, హోల్‌సేల్, కొనుగోలు రేట్‌తో.",
  "b1.rp_log": "మార్పుల రికార్డు",
