  "b2.farule1": "ఖాతాల తరుగుదల కంపెనీల చట్టం, 2013 షెడ్యూల్ II ప్రకారం: ప్రతి రకం అసెట్‌కు ఉపయోగ కాలం ఉంటుంది (ఉదా. కంప్యూటర్ 3 ఏళ్లు, ఫర్నిచర్ 10 ఏళ్లు, ప్లాంట్ మరియు మెషినరీ 15 ఏళ్లు, కారు 8 ఏళ్లు), మిగిలే విలువ సాధారణంగా ధరలో 5% మించదు, సంవత్సరం మధ్యలో జోడించిన లేదా అమ్మిన అసెట్‌కు వాడిన రోజులకే తరుగుదల. స్ట్రెయిట్ లైన్ (SLM: ప్రతి ఏడాది అదే మొత్తం) లేదా రిటన్ డౌన్ వాల్యూ (WDV: మిగిలిన మొత్తంపై స్థిర రేట్) ఎంచుకోండి. ప్రొప్రైటర్లు మరియు ఫర్మ్‌లు తరచుగా ఇదే పద్ధతి పాటిస్తారు; నిర్ణయం మీ అకౌంటెంట్‌దే.",
  "b2.farule2": "ఇన్‌కమ్ టాక్స్ తరుగుదల ప్రతి బ్లాక్‌కు విడిగా లెక్కిస్తారు: బ్లాక్ రేట్‌పై రిటన్ డౌన్ వాల్యూ (ఉదా. ప్లాంట్ మరియు మెషినరీ 15%, ఫర్నిచర్ 10%, కంప్యూటర్ 40%), సంవత్సరంలో 180 రోజుల కంటే తక్కువ వాడిన అసెట్‌కు సగం రేట్, అమ్మకం డబ్బు బ్లాక్ నుంచి తగ్గుతుంది. ఇది ఇన్‌కమ్ టాక్స్ రిటర్న్‌కు మాత్రమే, ఖాతాల్లో ఎప్పుడూ వేయరు. నింపిన రేట్లు సాధారణ బ్లాక్ రేట్లు: మీ అకౌంటెంట్‌తో నిర్ధారించుకోండి, ముఖ్యంగా 1 ఏప్రిల్ 2026 నుంచి ఇన్‌కమ్-టాక్స్ చట్టం, 2025 కింద వచ్చే సంవత్సరాలకు.",
  "b2.farule3": "మీరు 'తరుగుదల వేయండి' నొక్కినప్పుడే తరుగుదల మీ ఖాతాల్లోకి వెళ్తుంది: సంవత్సరం చివరి రోజు (లేదా మధ్యలో అయితే ఈరోజు) తేదీతో జర్నల్ ఎంట్రీ తరుగుదలను డెబిట్ చేసి ప్రతి అసెట్‌ను తగ్గిస్తుంది. తర్వాత అసెట్ మారిస్తే మళ్లీ వేయండి, తేడా మాత్రమే కలుస్తుంది.",
