  "b3.gd.p": "మీ సొంత Google Drive ద్వారా ఫోన్ మరియు కంప్యూటర్‌లో డేటాను ఒకేలా ఉంచండి. ఈ యాప్ అక్కడ చేసే ఒక్క ఫైల్‌ను మాత్రమే మేము చూడగలము, మా దగ్గరకు ఏదీ రాదు.",
