  "hs.x.maybe": "రేట్ నోటిఫికేషన్‌లో రేటు {r}, కానీ ఈ హెడింగ్‌లోని కొన్ని సర్వీసులకు మినహాయింపు ఉంది. GST వసూలు చేసే ముందు కింది మినహాయింపులు చూడండి.",
